CREATE TABLE public.pr_mastodon_actions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES public.pr_workspaces(id) ON DELETE CASCADE,
  connection_id text NOT NULL,
  actor_id uuid NOT NULL,
  action text NOT NULL,
  preview jsonb NOT NULL,
  digest text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  status text NOT NULL DEFAULT 'preview' CHECK (status IN ('preview','running','verified','accepted','rejected','uncertain','cancelled')),
  receipt jsonb,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '10 minutes',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(workspace_id,connection_id) REFERENCES public.pr_encrypted_credentials(workspace_id,connection_id) ON DELETE CASCADE
);
CREATE INDEX pr_mastodon_actions_connection ON public.pr_mastodon_actions(workspace_id,connection_id,created_at DESC);
CREATE INDEX pr_mastodon_actions_retention ON public.pr_mastodon_actions(created_at,id);
CREATE INDEX pr_mastodon_actions_recovery ON public.pr_mastodon_actions(updated_at,id) WHERE status='running';
CREATE TABLE public.pr_mastodon_health (
  workspace_id uuid NOT NULL,
  connection_id text NOT NULL,
  next_at timestamptz NOT NULL DEFAULT now(),
  checked_at timestamptz,
  state text NOT NULL DEFAULT 'pending',
  failures integer NOT NULL DEFAULT 0 CHECK (failures BETWEEN 0 AND 10),
  lease_id uuid,
  lease_until timestamptz,
  PRIMARY KEY(workspace_id,connection_id),
  FOREIGN KEY(workspace_id,connection_id) REFERENCES public.pr_encrypted_credentials(workspace_id,connection_id) ON DELETE CASCADE
);
CREATE INDEX pr_mastodon_health_due ON public.pr_mastodon_health(next_at,workspace_id,connection_id);
ALTER TABLE public.pr_mastodon_actions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pr_mastodon_actions FORCE ROW LEVEL SECURITY;
ALTER TABLE public.pr_mastodon_health ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pr_mastodon_health FORCE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.pr_mastodon_actions FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE POLICY service_only ON public.pr_mastodon_health FOR ALL TO service_role USING(true) WITH CHECK(true);
REVOKE ALL ON public.pr_mastodon_actions,public.pr_mastodon_health FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pr_mastodon_actions,public.pr_mastodon_health TO service_role;

-- Exact current3-provider constraint was checked above. Widen only; preserve Pinterest.
-- VALIDATE scans existing readings: requires separately approved remote execution/lock window.
ALTER TABLE public.pr_metric_reads DROP CONSTRAINT pr_metric_reads_provider_check;
ALTER TABLE public.pr_metric_reads ADD CONSTRAINT pr_metric_reads_provider_check
  CHECK (provider IN ('threads','instagram','pinterest','mastodon')) NOT VALID;
ALTER TABLE public.pr_metric_reads VALIDATE CONSTRAINT pr_metric_reads_provider_check;

